        int count = codes.Length;
        Span<double> resolved = count <= 256
            ? stackalloc double[count]
            : new double[count];

        int written = 0;
        for (int i = 0; i < codes.Length; i++)
        {
            bool found = prices is not null
                ? prices.TryGetValue(codes[i], out double p)
                : dict.TryGetValue(codes[i], out p);

            if (found)
                resolved[written++] = p;
        }

        return SimdSum(resolved[..written]);
    }

