    /// Overload accepting IEnumerable for backward compatibility.
    /// </summary>
    public double GetTotalPrice(IEnumerable<string> codes)
    {
        if (codes is IList<string> list)
        {
            // Avoid allocation by using the span-based path
            var arr = new string[list.Count];
            list.CopyTo(arr, 0);
            return GetTotalPrice(arr.AsSpan());
        }

        // Fallback: accumulate directly for streaming enumerables
        var prices = _frozenPrices;
        var dict = _prices;
        double total = 0;
        foreach (var code in codes)
        {
            bool found = prices is not null
                ? prices.TryGetValue(code, out double p)
                : dict.TryGetValue(code, out p);

            if (found)
                total += p;
        }
        return total;
    }

