            return frozen.TryGetValue(category, out var arr) ? arr : [];

        return _categoryIndex.TryGetValue(category, out var list) ? list : [];
    }

    /// <summary>
    /// SIMD-accelerated summation of a double span using hardware vectors.
    /// </summary>
    private static double SimdSum(ReadOnlySpan<double> values)
    {
        if (values.IsEmpty)
            return 0;

        int vectorSize = Vector<double>.Count;
        int i = 0;
        double sum = 0;

        if (Vector.IsHardwareAccelerated && values.Length >= vectorSize)
        {
            var vSum = Vector<double>.Zero;
            int limit = values.Length - (values.Length % vectorSize);

            ReadOnlySpan<double> aligned = values[..limit];
            // Process vector-width chunks
            for (; i < limit; i += vectorSize)
            {
                vSum += new Vector<double>(aligned[i..]);
            }

            // Horizontal reduction
            for (int lane = 0; lane < vectorSize; lane++)
                sum += vSum[lane];
